// Gom thông tin lỗi thành 1 bản ghi gọn để log / gửi thông báo
const e = $input.first().json;
return [{
  json: {
    workflow: e.workflow?.name,
    workflowId: e.workflow?.id,
    executionId: e.execution?.id,
    executionUrl: e.execution?.url,
    lastNode: e.execution?.lastNodeExecuted,
    message: e.execution?.error?.message ?? e.trigger?.error?.message,
    at: new Date().toISOString()
  }
}];
